contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 1000000000000000000); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 amount) public {
        c.AdjustDifficulty(amount); if (__ESBMC_reverted()) return;
        c.AdjustBetAmounts(amount); if (__ESBMC_reverted()) return;

        uint256 diff = c.currentDifficulty(); if (__ESBMC_reverted()) return;
        uint256 limit = c.currentBetLimit(); if (__ESBMC_reverted()) return;

        assert(diff <= limit);
    }
}

