pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 1000000000000000000);
    }

    function _run(uint256 amount) internal {
        try c.AdjustDifficulty(amount) {} catch { return; }
        try c.AdjustBetAmounts(amount) {} catch { return; }
        uint256 diff;
        try c.currentDifficulty() returns (uint256 __r) { diff = __r; } catch { return; }
        uint256 limit;
        try c.currentBetLimit() returns (uint256 __r) { limit = __r; } catch { return; }
        assertTrue(diff <= limit);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
